/**
 * 40 m² studio apartment — a single open room with one window, one front door
 * and a single "Living/Kitchen" zone. Used as a starting point for small unit
 * briefs. Deterministic ids (`site_empty`, `building_empty`, `level_0`, etc.)
 * are regenerated by the MCP tool via `cloneSceneGraph` before applying.
 */
// Footprint: 8 m × 5 m = 40 m² (centered at origin).
// Walls traverse the boundary counter-clockwise (right-handed XZ plane).
const W = 4; // half-width
const D = 2.5; // half-depth
function buildNodes() {
    const site = {
        object: 'node',
        id: 'site_empty',
        type: 'site',
        parentId: null,
        visible: true,
        metadata: {},
        polygon: {
            type: 'polygon',
            points: [
                [-15, -15],
                [15, -15],
                [15, 15],
                [-15, 15],
            ],
        },
        children: ['building_empty'],
    };
    const building = {
        object: 'node',
        id: 'building_empty',
        type: 'building',
        parentId: 'site_empty',
        visible: true,
        metadata: {},
        position: [0, 0, 0],
        rotation: [0, 0, 0],
        children: ['level_0'],
    };
    // Walls with deterministic ids; child ids are listed below after doors/windows
    // are created, so we fill this array after computing them.
    const wallIds = ['wall_n', 'wall_e', 'wall_s', 'wall_w'];
    // South wall carries the front door; west wall carries the window.
    const door = {
        object: 'node',
        id: 'door_front',
        type: 'door',
        parentId: 'wall_s',
        visible: true,
        metadata: {},
        wallId: 'wall_s',
        position: [0, 1.05, 0],
        rotation: [0, 0, 0],
        width: 0.9,
        height: 2.1,
        frameThickness: 0.05,
        frameDepth: 0.07,
        threshold: true,
        thresholdHeight: 0.02,
        hingesSide: 'left',
        swingDirection: 'inward',
        segments: [
            {
                type: 'panel',
                heightRatio: 0.4,
                columnRatios: [1],
                dividerThickness: 0.03,
                panelDepth: 0.01,
                panelInset: 0.04,
            },
            {
                type: 'panel',
                heightRatio: 0.6,
                columnRatios: [1],
                dividerThickness: 0.03,
                panelDepth: 0.01,
                panelInset: 0.04,
            },
        ],
        handle: true,
        handleHeight: 1.05,
        handleSide: 'right',
        contentPadding: [0.04, 0.04],
        doorCloser: false,
        panicBar: false,
        panicBarHeight: 1.0,
    };
    const windowNode = {
        object: 'node',
        id: 'window_w',
        type: 'window',
        parentId: 'wall_w',
        visible: true,
        metadata: {},
        wallId: 'wall_w',
        position: [0, 1.2, 0],
        rotation: [0, 0, 0],
        width: 1.5,
        height: 1.2,
        frameThickness: 0.05,
        frameDepth: 0.07,
        columnRatios: [1],
        rowRatios: [1],
        columnDividerThickness: 0.03,
        rowDividerThickness: 0.03,
        sill: true,
        sillDepth: 0.08,
        sillThickness: 0.03,
    };
    const wallNorth = {
        object: 'node',
        id: 'wall_n',
        type: 'wall',
        parentId: 'level_0',
        visible: true,
        metadata: {},
        children: [],
        thickness: 0.1,
        height: 2.5,
        start: [-W, -D],
        end: [W, -D],
        frontSide: 'unknown',
        backSide: 'unknown',
    };
    const wallEast = {
        object: 'node',
        id: 'wall_e',
        type: 'wall',
        parentId: 'level_0',
        visible: true,
        metadata: {},
        children: [],
        thickness: 0.1,
        height: 2.5,
        start: [W, -D],
        end: [W, D],
        frontSide: 'unknown',
        backSide: 'unknown',
    };
    const wallSouth = {
        object: 'node',
        id: 'wall_s',
        type: 'wall',
        parentId: 'level_0',
        visible: true,
        metadata: {},
        children: ['door_front'],
        thickness: 0.1,
        height: 2.5,
        start: [W, D],
        end: [-W, D],
        frontSide: 'unknown',
        backSide: 'unknown',
    };
    const wallWest = {
        object: 'node',
        id: 'wall_w',
        type: 'wall',
        parentId: 'level_0',
        visible: true,
        metadata: {},
        children: ['window_w'],
        thickness: 0.1,
        height: 2.5,
        start: [-W, D],
        end: [-W, -D],
        frontSide: 'unknown',
        backSide: 'unknown',
    };
    const zone = {
        object: 'node',
        id: 'zone_living',
        type: 'zone',
        parentId: 'level_0',
        visible: true,
        metadata: {},
        name: 'Living / Kitchen',
        color: '#60a5fa',
        polygon: [
            [-W, -D],
            [W, -D],
            [W, D],
            [-W, D],
        ],
    };
    const level = {
        object: 'node',
        id: 'level_0',
        type: 'level',
        parentId: 'building_empty',
        visible: true,
        metadata: {},
        level: 0,
        children: [...wallIds, 'zone_living'],
    };
    return {
        site,
        building,
        level,
        walls: [wallNorth, wallEast, wallSouth, wallWest],
        zone,
        door,
        window: windowNode,
    };
}
function buildTemplate() {
    const n = buildNodes();
    const nodes = {};
    for (const node of [n.site, n.building, n.level, ...n.walls, n.zone, n.door, n.window]) {
        nodes[node.id] = node;
    }
    return {
        nodes,
        rootNodeIds: ['site_empty'],
    };
}
export const template = buildTemplate();
export const metadata = {
    id: 'empty-studio',
    name: 'Empty studio',
    description: '40 m² single-room studio apartment: 4 walls, 1 living/kitchen zone, 1 window, 1 front door.',
};
